import collections
import os
import re

URL_RE = re.compile(r"https?://\S+")


def host_of(url):
    rest = url.split("://", 1)[1]
    host = re.split(r"[/:]", rest, maxsplit=1)[0].lower()
    if host.startswith("www."):
        host = host[4:]
    return host


def main():
    counts = collections.Counter()
    path = os.path.join("дані", "запити.log")
