        for line in f:
            for url in URL_RE.findall(line):
                host = host_of(url)
                if host:
                    counts[host] += 1
    top = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))[:3]
    for host, n in top:
        print(f"{host} {n}")


